import{d as c,C as t,o as g,c as b,j as a,a as o,E as s,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十二章","description":"以万物之奥、善与不善的不弃读道之贵，分辨美行与尊行等录文差异。","frontmatter":{"title":"道德经第六十二章","description":"以万物之奥、善与不善的不弃读道之贵，分辨美行与尊行等录文差异。","category":"guide","aliases":["道德经第六十二章","老子第六十二章","dao de jing chapter 62"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-62.md","filePath":"daoism/dao-de-jing/chapter-62.md","lastUpdated":1794189804000}'),u={name:"daoism/dao-de-jing/chapter-62.md"},y=c({...u,setup(p){const n=[{id:"shelter-of-all-things",label:"道者万物之奥",showLabel:!0,sentences:[["道者万物之",{text:"奥",glossary:"ao"},"。"]],note:["【白话】道是万物可以得到庇护的深处。这里用奥的处所之象，说明道并非只为某一类人或物保留。","【王弼注择要】「奥犹暧也，可得庇荫之辞。」本页循后半句庇荫释奥，不只译成难以理解的奥秘。","【读法】所据注以暧释奥的字面原样交代，具体取向由可得庇荫说明；这是本页所据的注法，不当作奥字所有语境的唯一义。"]},{id:"treasure-and-preservation",label:"善人之宝，不善人之所保",showLabel:!0,sentences:[["善人之",{text:"宝",glossary:"bao"},"，不善人之所",{text:"保",glossary:"bao-protect"},"。"]],note:["【白话】道是善人珍重而取用的宝，也是不善之人赖以保全、得以转变的凭依。宝与保字音相近，句中作用各有侧重。","【王弼注择要】宝下注「宝以为用也」，保下注「保以全也」。注分别突出取用与保全。","【读法】保留一个人改过与复归的可能，不等于肯定他的全部行为。联系第二十七章无弃人，可见本章所说不善并非永远不可改变的身份。"]},{id:"good-words-and-conduct",label:"美言可以市尊，美行可以加人",showLabel:!0,sentences:[["美言可以",{text:"市",glossary:"shi"},"尊，美行可以",{text:"加",glossary:"jia"},"人。"]],note:["【白话】按本站现文：美好的言语可以赢得尊重，美好的行为可以感召他人。句子进一步展开道之所以可贵，但美字不能只按悦耳好看来读。","【校读】所据经文作美言可以市尊行可以加人，按其注宜分作美言可以市，尊行可以加人；本站保留美行，不静默改成尊行。","【王弼注择要】「美言之，则可以夺众货之贾。」又说「尊行之，则千里之外应之」，并以「物无有贵于此也」突出道的价值。这里的注按尊行录文另列。","【读法】市在本站市尊中取赢得、求取尊重；加人另有超越他人等训法，本页结合古注远方响应暂作感召理解。古注的可市、尊行与本站市尊、美行句法不同，两条解释分列，不作为唯一训释。"]},{id:"not-abandoning-and-high-offices",label:"人之不善，何弃之有",showLabel:!0,sentences:[["人之不善，何弃之有？故立天子，置",{text:"三公",glossary:"sangong"},"，"]],note:["【白话】人即使有不善，为什么就要弃绝他呢？因此设立天子、设置三公这样的尊位，也应为了奉行这条使人有所归复的道。","【王弼注择要】「不善当保道以免放。」立天子置三公下注「言以尊行道也」，把尊位连到行道的职责。","【读法】何弃之有是何必弃之的反问。三公是古代最高辅政官职的统称；本页只取章内尊位应行道的关系，不将其具体制度一概定在某一朝。"]},{id:"offering-jade-or-dao",label:"不如坐进此道",showLabel:!0,sentences:[["虽有",{text:"拱璧",glossary:"gongbi"},"以先",{text:"驷马",glossary:"sima"},"，不如坐",{text:"进",glossary:"jin"},"此道。"]],note:["【白话】即使以双手捧持的宝璧为前导、配上四马之车进献，也不如安坐而进献这条道。珍贵的礼物在这里被拿来与道的价值相比。","【王弼注择要】「虽有拱抱宝璧以先驷马而进之，不如坐而进此道也。」注将坐进保留为与献璧马相对的一面。","【读法】先是使之在前、作为前导；进为进献。重心在所进为何物，不把坐读成从此不用实践，也不据此扩写一套未经核对的礼仪程序。"]},{id:"seeking-and-release-from-fault",label:"故为天下贵",showLabel:!0,sentences:[["古之所以",{text:"贵",glossary:"gui"},"此道者何？不曰求以得，有罪以免",{text:"邪",glossary:"ye"},"？故为天下",{text:"贵",glossary:"guivalued"},"。"]],note:["【白话】古人为什么看重此道呢？不正是因为求之可以有所得，有过罪的人也可以由此求免吗？因此，道为天下所看重。","【王弼注择要】「以求则得，求以免则得免。」注把两种求连到道可施及众人的作用；其意承接前文不善人亦有所保。","【读法】免在古代语境中说免于罪过或放弃之患；现代相参可读改过之门，不推出口称有道即可免除事实责任。此句首个贵是重视，末个贵是被看重，页内分别标义。"]}],r=[{id:"ao",term:"奥",sense:1},{id:"bao",term:"宝",sense:1},{id:"bao-protect",term:"保",sense:1},{id:"shi",term:"市",sense:1},{id:"jia",term:"加",sense:1},{id:"sangong",term:"三公",sense:1},{id:"gongbi",term:"拱璧",sense:1},{id:"sima",term:"驷马",sense:1},{id:"jin",term:"进",sense:1},{id:"gui",term:"贵",sense:1},{id:"guivalued",term:"贵",sense:3},{id:"ye",term:"邪",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十二章",tabindex:"-1"},[o("道德经第六十二章 "),a("a",{class:"header-anchor",href:"#道德经第六十二章","aria-label":'Permalink to "道德经第六十二章"'},"​")],-1)),s(i,{title:"道为什么既是善人之宝，也是不善人之所保",summary:"本章从道能庇护万物说起，不因人的不善就把他弃绝，再以宝玉车马对照进道，说明尊位也应服务于道。本站美行与录文尊行不同，古之所以贵此道一段也有录文字面差异，分别说明。",points:[{label:"先读",text:"奥依王注取可得庇荫的处所之义，宝以为用、保以全分别看。"},{label:"再辨",text:"不弃人并不取消对行为的判断；美行句先释本站现文，再列尊行的王注。"},{label:"后看",text:"拱璧驷马与坐进此道相较，最后把贵落在可求得、可改过的道路。"}],hint:"奥读 ào，拱璧读 gǒng bì，驷马读 sì mǎ；美行的行读 xíng，篇末邪作疑问语气，读 yé。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"善人之宝，不善人之所保。",tone:"分别用与全",guide:"王弼以为用、以全解释宝与保，善与不善都在道所可及之中。"},{text:"美言可以市尊，美行可以加人。",tone:"先说明字面差异",guide:"本站美行与录文尊行分列，古注的句法另行交代。"},{text:"虽有拱璧以先驷马，不如坐进此道。",tone:"尊位与礼物回到道",guide:"贵重的外在呈献，不如所进之道能使人有所归复。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:r}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
